fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    
    // Handle empty case
    if n == 0 {
        return Vec::new();
    }
    
    // Pre-allocate with exact capacity for efficiency
    let mut result = Vec::with_capacity(2 * n - 1);
    
    for (i, &num) in numbers.iter().enumerate() {
        // Add the current number
        result.push(num);
        
        // Add delimiter if not the last element
        if i < n - 1 {
            result.push(delim);
        }
    }
    
    result
}